<body>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

// Deterministic PRNG (Mulberry32) so low-poly jitter, claws, and spray are reproducible.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(183106);

// Palette sampled directly from print.jpg (Hokusai's Great Wave off Kanagawa).
const PAL = {
  skyTop:        new THREE.Color('#e4cea8'),
  skyMid:        new THREE.Color('#efe3c6'),
  skyBright:     new THREE.Color('#f7f0dd'),
  mistHorizon:   new THREE.Color('#7c7b75'),
  mistUpper:     new THREE.Color('#b6ae9b'),
  prussianDark:  new THREE.Color('#091e3c'),
  prussian:      new THREE.Color('#10315c'),
  indigo:        new THREE.Color('#1f527f'),
  cerulean:      new THREE.Color('#41789f'),
  foamShadow:    new THREE.Color('#b0cdd5'),
  foamMid:       new THREE.Color('#d7e6e6'),
  foamWhite:     new THREE.Color('#f5f0e1'),
  inkOutline:    new THREE.Color('#132c4c'),
  fujiDark:      new THREE.Color('#132f55'),
  fujiMid:       new THREE.Color('#214a75'),
  boatWood:      new THREE.Color('#dca970'),
  boatWoodLight: new THREE.Color('#eac28f'),
  boatWoodDark:  new THREE.Color('#7a5738'),
  boatInside:    new THREE.Color('#3b3127'),
  rowerBlue:     new THREE.Color('#224b73'),
  rowerSkin:     new THREE.Color('#ead7bd')
};

// Renderer setup
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.NoToneMapping;
document.body.appendChild(renderer.domElement);

// Scene & Camera: telephoto-like FOV preserves woodblock monumentality while giving true 3D depth.
const scene = new THREE.Scene();
scene.background = PAL.skyMid.clone();

const BASE_CAM_POS = new THREE.Vector3(0.0, 2.1, 26.5);
const BASE_CAM_LOOK = new THREE.Vector3(0.0, 2.1, 0.0);

const camera = new THREE.PerspectiveCamera(34, window.innerWidth / window.innerHeight, 0.5, 160);
camera.position.copy(BASE_CAM_POS);
camera.lookAt(BASE_CAM_LOOK);

// Lighting tuned for crisp faceted low-poly shading that keeps woodblock colors clean.
const hemiLight = new THREE.HemisphereLight('#fbf5e6', '#2a4d70', 1.15);
scene.add(hemiLight);

const keyLight = new THREE.DirectionalLight('#fff6e3', 1.05);
keyLight.position.set(16, 22, 18);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight('#9ec2d9', 0.45);
fillLight.position.set(-18, 6, 12);
scene.add(fillLight);

const rimLight = new THREE.DirectionalLight('#f4e2be', 0.35);
rimLight.position.set(4, 14, -18);
scene.add(rimLight);

// Shared flat-shaded materials
function makeFlatVertexMat(side = THREE.FrontSide) {
  return new THREE.MeshStandardMaterial({
    vertexColors: true,
    flatShading: true,
    roughness: 0.88,
    metalness: 0.02,
    side
  });
}

function makeSolidMat(color, roughness = 0.86, side = THREE.FrontSide) {
  return new THREE.MeshStandardMaterial({
    color,
    flatShading: true,
    roughness,
    metalness: 0.02,
    side
  });
}

const outlineMat = new THREE.MeshBasicMaterial({
  color: PAL.inkOutline,
  side: THREE.BackSide
});

